#!/usr/bin/env bash
set -euo pipefail

PROJECT_DIR="$(cd "$(dirname "$0")" && pwd)"
cd "$PROJECT_DIR"
PORT="${PORT:-3000}"
OUTPUT_DIR="$PROJECT_DIR/dist"

run() {
  /usr/bin/time -p "$@"
}

# Build an existing project when present; static projects are copied into dist.
if [[ -f package.json ]]; then
  if [[ -f package-lock.json ]]; then
    run npm ci --no-audit --no-fund
  else
    run npm install --no-audit --no-fund
  fi
  if run node -e "const p=require('./package.json');process.exit(p.scripts?.build?0:1)"; then
    run npm run build
  elif [[ ! -f index.html ]]; then
    echo 'package.json has no build script and project has no index.html.' >&2
    exit 1
  fi
  if [[ ! -f "$OUTPUT_DIR/index.html" && -f index.html ]]; then
    run mkdir -p "$OUTPUT_DIR"
    run cp -R index.html "$OUTPUT_DIR/index.html"
    [[ ! -d assets ]] || run cp -R assets "$OUTPUT_DIR/assets"
  fi
elif [[ -f index.html ]]; then
  run mkdir -p "$OUTPUT_DIR"
  run cp -R index.html "$OUTPUT_DIR/index.html"
  [[ ! -d assets ]] || run cp -R assets "$OUTPUT_DIR/assets"
else
  # This repository had no application source. Keep a self-contained playable
  # fallback in the project build directory so the preview is always runnable.
  run mkdir -p "$OUTPUT_DIR"
  /usr/bin/time -p cat > "$OUTPUT_DIR/index.html" <<'HTML'
<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no"><meta name="theme-color" content="#101813"><title>Jurassic Rush</title>
<style>
:root{color-scheme:dark;--lime:#c8ff6a;--ink:#101813}*{box-sizing:border-box}body{margin:0;background:#101813;color:#f5f4e9;font:500 14px/1.4 Inter,system-ui,sans-serif;overflow:hidden}button{font:inherit;color:inherit;border:0;cursor:pointer}.game{height:100dvh;min-height:570px;max-width:1500px;margin:auto;display:grid;grid-template-columns:1fr 320px;background:radial-gradient(ellipse at 48% 38%,#253c2b,#101813 70%)}.stage{position:relative;min-width:0;overflow:hidden;background:linear-gradient(180deg,#8ea77c 0%,#b1b886 42%,#556c3e 43%,#213724 100%)}.stage:after{content:"";position:absolute;inset:43% 0 0;background:repeating-linear-gradient(165deg,transparent 0 68px,#9fb36b16 69px 72px),linear-gradient(0deg,#172e20,#45633b);z-index:0}.sun{position:absolute;right:14%;top:9%;width:92px;height:92px;background:#ffe69d;border-radius:50%;filter:blur(1px);box-shadow:0 0 65px #ffe69d88}.mountains{position:absolute;top:24%;left:0;width:100%;height:28%;background:#687b5b;clip-path:polygon(0 60%,12% 35%,22% 68%,38% 0,58% 63%,70% 22%,90% 68%,100% 38%,100% 100%,0 100%);opacity:.75}.hud{position:absolute;z-index:3;top:20px;left:22px;right:22px;display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.brand{font-size:11px;font-weight:900;letter-spacing:.18em;color:#18251a;background:#d7e4b7;padding:8px 11px;border-radius:5px}.pill{background:#122018d9;border:1px solid #ffffff24;border-radius:8px;padding:10px 13px;box-shadow:0 5px 20px #0002}.level{font-size:11px;letter-spacing:.14em;color:#c8ff6a}.xpbar{width:180px;height:5px;margin-top:8px;background:#ffffff25;border-radius:8px;overflow:hidden}.xpbar i{display:block;width:34%;height:100%;background:#c8ff6a;transition:width .3s}.stat{display:flex;gap:7px;align-items:center;font-size:13px;font-weight:800}.side{padding:27px 22px;display:flex;flex-direction:column;gap:19px;background:#111a14;border-left:1px solid #ffffff12;overflow:auto}.eyebrow{font-size:10px;letter-spacing:.2em;color:#9eaf93;font-weight:800}.title{font-size:25px;font-weight:900;letter-spacing:-.04em;margin:4px 0}.desc{font-size:12px;color:#aab5a5;margin:0}.card{background:#1b281d;border:1px solid #ffffff13;border-radius:10px;padding:15px}.cardhead{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.cardhead strong{font-size:12px;letter-spacing:.06em}.badge{color:#d7f897;font-size:10px}.dino{display:flex;gap:12px;align-items:center}.avatar{width:56px;height:56px;background:#304b31;border-radius:9px;display:grid;place-items:center;font-size:34px}.dino b{display:block;font-size:14px}.dino small{color:#aab5a5;font-size:11px}.loot{display:grid;grid-template-columns:1fr auto;align-items:center;gap:6px}.loot .icon{grid-row:span 2;font-size:38px;margin-right:8px}.loot button,.primary{background:#c8ff6a;color:#182217;font-weight:900;border-radius:7px;padding:11px 13px}.loot button{grid-column:2;grid-row:1 / span 2}.loot button:disabled{opacity:.55}.missions{display:flex;flex-direction:column;gap:11px}.mission{display:flex;justify-content:space-between;font-size:11px;color:#d7dfd1}.mission span:last-child{color:#c8ff6a;font-weight:800}.hint{margin-top:auto;font-size:10px;color:#85927f;line-height:1.55}.ground{position:absolute;z-index:1;inset:45% 0 0;pointer-events:none}.tree{position:absolute;bottom:40%;font-size:60px;filter:drop-shadow(0 8px 4px #17231855)}.tree.a{left:10%}.tree.b{right:11%;bottom:52%;font-size:46px}.dinosaur{position:absolute;z-index:2;left:46%;top:54%;font-size:94px;transform:translate(-50%,-50%);filter:drop-shadow(0 12px 8px #1119);transition:all .2s}.dinosaur.attack{animation:bite .28s ease}.person{position:absolute;z-index:2;font-size:36px;filter:drop-shadow(0 7px 4px #1224);transition:all .3s}.person.dead{opacity:0;transform:translateY(25px) scale(.5)}.p1{left:23%;top:64%}.p2{left:69%;top:57%}.p3{left:79%;top:76%;font-size:30px}.chestworld{position:absolute;z-index:2;left:60%;top:72%;font-size:36px;filter:drop-shadow(0 6px 3px #1424)}.float{position:absolute;z-index:4;font-size:15px;color:#eaffbd;font-weight:900;animation:float 1s forwards;pointer-events:none}.controls{position:absolute;z-index:4;bottom:20px;left:20px;display:flex;gap:8px}.controls button,.attackbtn{background:#111c16d9;border:1px solid #ffffff38;border-radius:9px;width:49px;height:48px;font-size:20px;backdrop-filter:blur(8px);touch-action:none}.attackbtn{position:absolute;z-index:4;right:24px;bottom:22px;width:76px;height:76px;border-radius:50%;background:#c8ff6a;color:#1b291c;font-size:28px;box-shadow:0 0 0 8px #c8ff6a30}.toast{position:absolute;z-index:5;left:50%;top:25%;transform:translate(-50%,-20px);opacity:0;background:#142018eF;border:1px solid #c8ff6a66;border-radius:9px;padding:12px 16px;font-weight:900;transition:.3s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}@keyframes bite{50%{transform:translate(-40%,-50%) scale(1.25) rotate(-8deg)}}@keyframes float{to{opacity:0;transform:translateY(-42px)}}@media(max-width:760px){.game{display:block;min-height:0;height:100dvh}.stage{height:62dvh;min-height:430px}.side{height:38dvh;padding:14px 16px;display:grid;grid-template-columns:1fr 1fr;gap:10px;overflow:auto}.side>.intro,.side>.hint{display:none}.side .card{padding:10px}.cardhead{margin-bottom:7px}.loot .icon{font-size:29px}.xpbar{width:min(28vw,150px)}.hud{top:12px;left:12px;right:12px}.tree.a{left:2%}.tree.b{right:2%}.dinosaur{font-size:76px}.person{font-size:30px}.controls{bottom:12px;left:12px}.controls button{width:43px;height:43px}.attackbtn{width:64px;height:64px;right:14px;bottom:12px}.brand{padding:7px;font-size:9px}.pill{padding:8px}.stat{font-size:11px}}
</style></head><body><main class="game"><section class="stage" id="stage"><div class="sun"></div><div class="mountains"></div><div class="hud"><div class="brand">JURASSIC RUSH&nbsp; / &nbsp;WILD VALLEY</div><div class="pill"><div class="level">LEVEL <b id="level">01</b> <span id="evo">· JUVENILE</span></div><div class="xpbar"><i id="bar"></i></div></div><div class="pill stat">🪙 <span id="money">120</span></div></div><div class="ground"><span class="tree a">🌴</span><span class="tree b">🌳</span></div><div id="dino" class="dinosaur">🦖</div><span class="person p1" data-xp="20">🧑‍🌾</span><span class="person p2" data-xp="35">🧑‍🚀</span><span class="person p3" data-xp="50">🧙</span><span class="chestworld" id="worldChest">🧰</span><div class="toast" id="toast"></div><div class="controls"><button data-move="left" aria-label="Mover para esquerda">←</button><button data-move="up" aria-label="Mover para frente">↑</button><button data-move="down" aria-label="Mover para trás">↓</button><button data-move="right" aria-label="Mover para direita">→</button></div><button class="attackbtn" id="attack" aria-label="Atacar">⚔</button></section><aside class="side"><div class="intro"><div class="eyebrow">SEU PREDADOR</div><div class="title">Evolua. Domine.</div><p class="desc">Caçe para ganhar XP, suba de nível e abra baús lendários.</p></div><div class="card"><div class="cardhead"><strong>EVOLUÇÃO ATUAL</strong><span class="badge" id="levelTag">LV. 01</span></div><div class="dino"><div class="avatar" id="avatar">🦖</div><div><b id="dinoName">Rex Filhote</b><small id="dinoPower">Poder 12 · XP 0 / 100</small></div></div></div><div class="card"><div class="cardhead"><strong>BAÚ MISTERIOSO</strong><span class="badge">GRÁTIS</span></div><div class="loot"><span class="icon">🎁</span><b>Recompensa surpresa</b><small style="color:#aab5a5">Dino novo ou moedas</small><button id="openChest">ABRIR</button></div></div><div class="card"><div class="cardhead"><strong>DESAFIOS DA ILHA</strong><span class="badge">HOJE</span></div><div class="missions"><div class="mission"><span>Caçe 3 exploradores</span><span id="huntCount">0 / 3</span></div><div class="mission"><span>Encontre o baú</span><span>+100 🪙</span></div></div></div><div class="hint">TOQUE em ⚔ para caçar · Use as setas para explorar<br>Sobreviva na ilha e torne-se o rei dos dinossauros.</div></aside></main>
<script>
(()=>{let xp=0,level=1,money=120,hunts=0,chest=0;const stage=document.querySelector('#stage'),dino=document.querySelector('#dino'),people=[...document.querySelectorAll('.person')],xpNeed=()=>level*100,names=['Rex Filhote','Raptor Veloz','Triceratops','Espinossauro','T-Rex Alfa','Dragão Primordial'],skins=['🦖','🦎','🦕','🐊','🦖','🐉'];function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1700)}function update(){document.querySelector('#level').textContent=String(level).padStart(2,'0');document.querySelector('#levelTag').textContent='LV. '+String(level).padStart(2,'0');document.querySelector('#evo').textContent='· '+(['JUVENILE','HUNTER','TANK','APEX','ALPHA','MYTHIC'][Math.min(level-1,5)]);document.querySelector('#money').textContent=money;document.querySelector('#bar').style.width=Math.min(100,xp/xpNeed()*100)+'%';document.querySelector('#dinoPower').textContent='Poder '+(12+level*8)+' · XP '+xp+' / '+xpNeed();document.querySelector('#dinoName').textContent=names[Math.min(level-1,5)];document.querySelector('#avatar').textContent=skins[Math.min(level-1,5)];dino.textContent=skins[Math.min(level-1,5)];document.querySelector('#huntCount').textContent=Math.min(hunts,3)+' / 3'}function move(dir){const r=dino.getBoundingClientRect(),s=stage.getBoundingClientRect();let x=r.left-s.left+r.width/2,y=r.top-s.top+r.height/2,step=22;if(dir==='left')x-=step;if(dir==='right')x+=step;if(dir==='up')y-=step;if(dir==='down')y+=step;dino.style.left=Math.max(50,Math.min(s.width-50,x))+'px';dino.style.top=Math.max(130,Math.min(s.height-105,y))+'px'}function attack(){dino.classList.remove('attack');void dino.offsetWidth;dino.classList.add('attack');let live=people.filter(p=>!p.classList.contains('dead'));if(!live.length){toast('Sem alvos por perto! Explore a ilha.');return}const target=live.sort((a,b)=>{let r=dino.getBoundingClientRect(),ra=a.getBoundingClientRect(),rb=b.getBoundingClientRect();return Math.hypot(ra.x-r.x,ra.y-r.y)-Math.hypot(rb.x-r.x,rb.y-r.y)})[0];target.classList.add('dead');let gain=Number(target.dataset.xp);xp+=gain;hunts++;let box=target.getBoundingClientRect(),sb=stage.getBoundingClientRect(),f=document.createElement('span');f.className='float';f.textContent='+'+gain+' XP';f.style.left=(box.left-sb.left)+'px';f.style.top=(box.top-sb.top)+'px';stage.append(f);setTimeout(()=>f.remove(),1000);toast('Alvo caçado! +'+gain+' XP');while(xp>=xpNeed()){xp-=xpNeed();level++;toast('EVOLUÇÃO! '+names[Math.min(level-1,5)]+' desbloqueado!')}update();setTimeout(()=>{target.classList.remove('dead');const spots=[['23%','64%'],['69%','57%'],['79%','76%']];target.style.left=spots[Math.floor(Math.random()*3)][0];target.style.top=spots[Math.floor(Math.random()*3)][1]},2800)}document.querySelector('#attack').addEventListener('click',attack);document.querySelectorAll('[data-move]').forEach(b=>{b.addEventListener('click',()=>move(b.dataset.move));b.addEventListener('touchstart',e=>{e.preventDefault();move(b.dataset.move)},{passive:false})});document.querySelector('#openChest').addEventListener('click',e=>{if(chest){toast('O baú volta em '+chest+'s');return}chest=12;e.currentTarget.disabled=true;document.querySelector('#worldChest').textContent='📦';setTimeout(()=>{let prize=Math.random()<.48;if(prize){level++;xp=0;toast('NOVO DINOSSAURO! '+names[Math.min(level-1,5)])}else{let coins=100+Math.floor(Math.random()*301);money+=coins;toast('Baú aberto! +'+coins+' moedas')}update();document.querySelector('#worldChest').textContent='🪙';let timer=setInterval(()=>{chest--;if(chest<=0){clearInterval(timer);e.currentTarget.disabled=false;document.querySelector('#worldChest').textContent='🧰'}},1000)},650)});window.addEventListener('keydown',e=>{({ArrowLeft:()=>move('left'),ArrowRight:()=>move('right'),ArrowUp:()=>move('up'),ArrowDown:()=>move('down'),' ':attack})[e.key]?.()});update()})();
</script></body></html>
HTML
fi

[[ -f "$OUTPUT_DIR/index.html" ]] || { echo "Build output missing $OUTPUT_DIR/index.html" >&2; exit 1; }
export PROJECT_DIR OUTPUT_DIR PORT OPENCODE_WEB_DIR
run node --input-type=module -e '
import { createServer } from "node:http";
import { existsSync, readFileSync, statSync, mkdirSync, writeFileSync } from "node:fs";
import { resolve, join, extname } from "node:path";
const root=resolve(process.env.OUTPUT_DIR), project=resolve(process.env.PROJECT_DIR);
if(!root.startsWith(project+"/")||!existsSync(join(root,"index.html"))) throw new Error("Static build must be inside PROJECT_DIR and contain index.html");
const metadata=process.env.OPENCODE_WEB_DIR;
if(metadata){mkdirSync(metadata,{recursive:true});writeFileSync(join(metadata,"deployment-output.json"),JSON.stringify({project,directory:root}));}
const types={".html":"text/html; charset=utf-8",".js":"application/javascript",".css":"text/css",".json":"application/json",".svg":"image/svg+xml",".png":"image/png",".jpg":"image/jpeg",".webp":"image/webp"};
createServer((req,res)=>{try{const url=new URL(req.url,"http://localhost"),file=resolve(root,"."+decodeURIComponent(url.pathname));if(file!==root&&!file.startsWith(root+"/")){res.writeHead(403);res.end();return;}const target=statSync(file).isDirectory()?join(file,"index.html"):file;res.setHeader("Content-Type",types[extname(target)]||"application/octet-stream");res.setHeader("Cache-Control","no-store");res.end(readFileSync(target));}catch{res.writeHead(404);res.end("Not found");}}).listen(Number(process.env.PORT),"0.0.0.0",()=>console.log(`Serving ${root} on port ${process.env.PORT}`));
'